<script setup lang="ts">
/**
 * The mandatory message for a view with nothing to show (`design/components/empty-state.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/empty-state.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type VNode } from 'vue'

import { Icon, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/empty-state.module.css'
import Inline from '../layout/Inline.vue'

export interface EmptyStateProps {
  /**
   * What to do about it.
   */
  description?: string
  icon?: IconRole
  /**
   * Describes the situation, such as "No tickets yet" rather than "Empty".
   */
  title: string
  /**
   * One Button, `soft`/`accent` by convention, so the page's own primary stays primary.
   */
  action?: VNode
  /**
   * A `ghost` Button, such as "Clear filters".
   */
  secondaryAction?: VNode
}

defineOptions({ name: 'EmptyState', inheritAttrs: false })

withDefaults(defineProps<Omit<EmptyStateProps, 'action' | 'secondaryAction'>>(), { icon: 'inbox' })
defineSlots<{
  action?: (props: Record<string, never>) => unknown
  secondaryAction?: (props: Record<string, never>) => unknown
}>()
</script>

<template>
  <div :class="styles.empty" data-member="empty-state">
    <!-- well -->
    <span :class="styles.well">
      <Icon :name="icon" size="lg" />
    </span>
    <!-- title -->
    <h2 :class="styles.title">
      {{ title }}
    </h2>
    <!-- description -->
    <p v-if="description !== undefined" :class="styles.description">
      {{ description }}
    </p>
    <!-- actions -->
    <div v-if="$slots.action || $slots.secondaryAction" :class="styles.actions">
      <Inline :gap="3" :wrap="true" justify="center">
        <slot name="action" />
        <slot name="secondaryAction" />
      </Inline>
    </div>
  </div>
</template>
